import type {FC} from 'react';
import React from 'react';

import {TargetDart} from '@gravity-ui/icons';

import type {EntityIconProps} from '../EntityIcon';
import {EntityIcon} from '../EntityIcon';

export type GoalIconProps = {
    goalId: number | string;
} & Omit<EntityIconProps, 'data' | 'id' | 'alpha'>;

export const GoalIcon: FC<GoalIconProps> = ({goalId, ...props}) => (
    <EntityIcon data={TargetDart} id={goalId} type="goal" {...props} />
);
